head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gViewerStat = "R";
scwin.clickIrseq;
scwin.vScrenID = "ULDSTF30302.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var com_nm = txb_isur_cd.getValue();
    url = "/IRMgt.do?method=listIRInfo&COM_CODE=" + com_nm + "&FROM_DATE=" + edt_SDate.getValue() + "&TO_DATE=" + edt_EDate.getValue() + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    irlist_Data.DataID = encodeURI(url);
    irlist_Data.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setIrSeq = function(obj) {
    if (scwin.clickIrseq != "input") {
        scwin.clickIrseq = irlist_Data.getCellData(eval(obj), "IR_SEQ");
    }
};
scwin.fn_getIrSeq = function() {
    return scwin.clickIrseq;
};
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = irlist_Data.getCellData(eval(obj), "ACPT_NO");
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.irlist_Data_OnLoadError = function() {
    $c.stf.alert_error(irlist_Data);
    $c.cm.CloseWin('', grd_Grid);
    //alert('irlist_Data.OnLoadError() '  + irlist_Data.errorMsg);

};
scwin.irlist_Data_OnLoadCompleted = function(rowcount) {
    if (irlist_Data.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + irlist_Data.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            irlist_Data.removeAll();
        }
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Input_onclick = async function() {
    scwin.clickIrseq = "input";
    await $c.frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30303.gfm", "IR정보 입력", 200, 100, 730, 420 + 30, "window");
    scwin.clickIrseq = "";
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "IR처리", "", "2");
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == 'COM_NM') {
        scwin.gIsurCd = irlist_Data.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
    if (colid == 'HLD_LOC') {
        scwin.fn_setIrSeq(row);
        await $c.frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30303.gfm", "IR정보 수정", 200, 100, 730, 420 + 30, "window");
        scwin.fn_list_sync();
    }
    if (colid == 'ORG_TEXT') {
        if (irlist_Data.getCellData(row, "ORG_TEXT") != "") {
            //fn_setContnId(row);
            $c.stf.fn_OpenDisclViewer(irlist_Data.getCellData(row, "ACPT_NO"), "R");
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜	
    edt_EDate.setValue(vCurDate);
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (js_market == '1' || js_market == '2' || js_market == '6') {
        $c.stf.showObj(panel_mkt, false);
    }
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
